<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/classes/GreenPortalDatabase.php';
require_once dirname(__DIR__) . '/classes/UsuarioSessao.php';
require_once dirname(__DIR__) . '/classes/PermissaoTransacao.php';
require_once dirname(__DIR__) . '/classes/TransactionSecurity.php';
require_once dirname(__DIR__) . '/classes/IdiomaService.php';
// Textos em Administração › Textos e idiomas (grupo requisito_responsabilidades)
$R = static fn(string $k, string $pt, string $en, string $es): string => IdiomaService::t('requisito_responsabilidades.' . $k, ['pt' => $pt, 'en' => $en, 'es' => $es]);
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
if (empty($_SESSION['autenticado']) || empty($_SESSION['tenant']['banco_dados'])) { http_response_code(401); exit($R('erro.sessao', 'Sessão expirada.', 'Your session has expired.', 'Su sesión expiró.')); }
$env = GreenPortalDatabase::env(); $pdo = TransactionSecurity::connect('REQUISITOS_LEGAIS');
if (!UsuarioSessao::atualizar($pdo, $_SESSION)) { http_response_code(401); exit($R('erro.sessao', 'Sessão expirada.', 'Your session has expired.', 'Su sesión expiró.')); }
if (!PermissaoTransacao::obter('REQUISITOS_LEGAIS')['pode_visualizar']) { http_response_code(403); exit($R('erro.sem_permissao', 'Sem permissão para consultar responsabilidades.', 'Not allowed to view responsibilities.', 'Sin permiso para consultar responsabilidades.')); }
$id = filter_input(INPUT_GET, 'CODSITUACAO', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]); if (!$id) { http_response_code(400); exit($R('erro.situacao', 'Situação inválida.', 'Invalid status record.', 'Situación no válida.')); }
$json = static fn(array $value): string => json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES); $e = static fn(mixed $value): string => htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
$rows = GreenPortalDatabase::call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,1000,0)', ['tabela' => 'vw_responsabilidade_requisitos', 'filtros' => $json(['CODSITUACAO' => $id])]); $situation = $rows[0] ?? [];
?><!doctype html><html lang="<?= IdiomaService::idioma() === 'pt' ? 'pt-BR' : $e(IdiomaService::idioma()) ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $e($R('titulo', 'Responsabilidades do requisito', 'Requirement responsibilities', 'Responsabilidades del requisito')) ?></title><link rel="stylesheet" href="../assets/vendor/bootstrap/css/bootstrap.min.css?v=2"><link rel="stylesheet" href="../assets/vendor/bootstrap-icons/bootstrap-icons.css?v=2"><link rel="stylesheet" href="../assets/css/app.css?v=1"><?php require_once dirname(__DIR__) . '/components/pagina_padrao.php'; greenPortalEstiloPagina(); ?></head><body class="p-3 bg-light"><main class="container-fluid"><div class="mb-3"><h4 class="mb-1"><i class="bi bi-people me-2"></i><?= $e($R('titulo', 'Responsabilidades do requisito', 'Requirement responsibilities', 'Responsabilidades del requisito')) ?></h4><div class="text-muted small"><?= $e($R('situacao', 'Situação', 'Status record', 'Situación')) ?> <?= $e($id) ?> — <?= $e($situation['DESCRICAO_SITUACAO'] ?? $R('sem_descricao', 'Sem descrição', 'No description', 'Sin descripción')) ?></div></div><?php if (!$rows): ?><div class="alert alert-info"><?= $e($R('vazio', 'Não há responsabilidades cadastradas para esta situação.', 'There are no responsibilities registered for this status record.', 'No hay responsabilidades registradas para esta situación.')) ?></div><?php else: ?><div class="table-responsive border rounded bg-white"><table class="table table-sm table-hover align-middle mb-0"><thead class="table-light"><tr><th><?= $e($R('col.finalidade', 'Finalidade', 'Purpose', 'Finalidad')) ?></th><th><?= $e($R('col.responsavel', 'Responsável', 'Owner', 'Responsable')) ?></th><th><?= $e($R('col.destino', 'Destino', 'Assignee type', 'Destino')) ?></th><th><?= $e($R('col.origem', 'Origem', 'Origin', 'Origen')) ?></th><th><?= $e($R('col.situacao', 'Situação', 'Status', 'Situación')) ?></th><th><?= $e($R('col.validade', 'Validade', 'Validity', 'Validez')) ?></th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr data-testid="responsibility-consulta-row" data-situacao="<?= $e($row['SITUACAO']) ?>"><td><?= $e($row['TIPO_NOME'] ?: $R('responsavel_padrao', 'Responsável pelo requisito', 'Requirement owner', 'Responsable del requisito')) ?></td><td><?= $e($row['RESPONSAVEL_EXIBICAO']) ?><?php if (!empty($row['USUARIOS_ATIVOS_GRUPO'])): ?><div class="small text-muted"><?= $e(str_replace('{n}', (string)$row['USUARIOS_ATIVOS_GRUPO'], $R('usuarios_ativos', '{n} usuário(s) ativo(s)', '{n} active user(s)', '{n} usuario(s) activo(s)'))) ?></div><?php endif; ?></td><td><?= $e($row['TIPO_DESTINO'] === 'GRUPO' ? $R('destino.grupo', 'Grupo', 'Group', 'Grupo') : $R('destino.usuario', 'Usuário', 'User', 'Usuario')) ?></td><td><?= $e($row['ORIGEM']) ?></td><td><span class="badge <?= $row['SITUACAO'] === 'ATIVA' ? 'text-bg-success' : 'text-bg-secondary' ?>"><?= $e($row['SITUACAO']) ?></span></td><td><?= $e($row['VALIDO_DE']) ?><?= $row['VALIDO_ATE'] ? ' ' . $e($R('validade.ate', 'a', 'to', 'a')) . ' ' . $e($row['VALIDO_ATE']) : ' ' . $e($R('validade.em_diante', 'em diante', 'onwards', 'en adelante')) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></main></body></html>
